CREATE OR REPLACE PROCEDURE sp(para_Election_Cycle VARCHAR2, para_Registration_integer VARCHAR2, para_Treasurer_Vote NUMBER, para_Advisor NUMBER) IS
    CURSOR ref_cursor1 IS SELECT * FROM "Voting_record" FOR UPDATE;
    CURSOR ref_cursor2 IS SELECT * FROM "Student" FOR UPDATE;
    rec1 ref_cursor1%ROWTYPE;
    rec2 ref_cursor2%ROWTYPE;
BEGIN
    INSERT INTO "Voting_record" ("Election_Cycle") VALUES (para_Election_Cycle);
    OPEN ref_cursor1;
    LOOP
        FETCH ref_cursor1 INTO rec1;
        EXIT WHEN ref_cursor1%NOTFOUND;

        rec1."Registration_integer" := para_Registration_integer || rec1."Election_Cycle";
        IF rec1."Treasurer_Vote" IS NOT NULL AND para_Treasurer_Vote IS NOT NULL AND rec1."Treasurer_Vote" = para_Treasurer_Vote THEN
            rec1."Registration_integer" := rec1."Registration_integer" || rec1."Secretary_Vote";
        END IF;

        IF rec1."Treasurer_Vote" IS NULL AND para_Treasurer_Vote IS NOT NULL THEN
            rec1."Treasurer_Vote" := para_Treasurer_Vote;
        END IF;

        IF (rec1."Election_Cycle" = para_Election_Cycle) OR (rec1."Election_Cycle" IS NULL AND para_Election_Cycle IS NULL) THEN
            rec1."President_Vote" := para_Treasurer_Vote;
        END IF;

        UPDATE "Voting_record"
        SET "Registration_integer" = rec1."Registration_integer",
            "Treasurer_Vote" = rec1."Treasurer_Vote",
            "President_Vote" = rec1."President_Vote"
        WHERE CURRENT OF ref_cursor1;
    END LOOP;
    CLOSE ref_cursor1;
    IF para_Treasurer_Vote > 50 THEN
        DELETE FROM "Voting_record" vr WHERE vr."StuID" IN (SELECT s."StuID" FROM "Student" s WHERE s."Advisor" = para_Advisor);
        OPEN ref_cursor2;
        LOOP
            FETCH ref_cursor2 INTO rec2;
            EXIT WHEN ref_cursor2%NOTFOUND;
            IF rec2."Advisor" = para_Advisor THEN
                DELETE FROM "Student" WHERE CURRENT OF ref_cursor2;
            END IF;
        END LOOP;
        CLOSE ref_cursor2;
    END IF;
END;

